-- ===== 20261024000300_membership_location.sql =====
-- Where the gym is: a branch name, area or address. Free text, optional.
alter table public.memberships
  add column if not exists location text check (location is null or char_length(location) <= 120);

-- ===== 20261024000400_membership_coordinates.sql =====
-- Exact map position of the gym, picked on a map. Both set or both empty.
alter table public.memberships
  add column if not exists latitude numeric(9, 6),
  add column if not exists longitude numeric(9, 6);

alter table public.memberships drop constraint if exists memberships_coordinates_check;
alter table public.memberships
  add constraint memberships_coordinates_check check (
    (latitude is null) = (longitude is null)
    and (latitude is null or latitude between -90 and 90)
    and (longitude is null or longitude between -180 and 180)
  );

-- ===== 20261024000500_log_photos.sql =====
-- Photos attached to a daily check-in or a weigh-in (selfies, gym places).
-- Files live in the private progress-photos bucket under <user id>/log/<photo id>.<ext>,
-- which the existing storage policy already covers (first folder is the user id).
-- Deleting the check-in or weigh-in deletes its rows here; the app removes the files first.

create table if not exists public.log_photos (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  checkin_id uuid references public.daily_checkins (id) on delete cascade,
  weight_id uuid references public.weight_logs (id) on delete cascade,
  storage_path text not null,
  created_at timestamptz not null default now(),
  -- A photo belongs to exactly one entry.
  check (num_nonnulls(checkin_id, weight_id) = 1)
);

create index if not exists log_photos_user_idx on public.log_photos (user_id, created_at desc);
create index if not exists log_photos_checkin_idx on public.log_photos (checkin_id);
create index if not exists log_photos_weight_idx on public.log_photos (weight_id);

alter table public.log_photos enable row level security;

drop policy if exists "log_photos owner" on public.log_photos;
create policy "log_photos owner" on public.log_photos
  for all to authenticated
  using (user_id = (select auth.uid()))
  with check (
    user_id = (select auth.uid())
    -- The entry must be the user's own, so a photo cannot be attached to someone else's row.
    and (checkin_id is null or exists (
      select 1 from public.daily_checkins c
      where c.id = checkin_id and c.user_id = (select auth.uid())))
    and (weight_id is null or exists (
      select 1 from public.weight_logs w
      where w.id = weight_id and w.user_id = (select auth.uid())))
  );

-- ===== 20261028000000_user_settings.sql =====
-- Per user preferences (country, weight unit, default currency) and the currency of each membership price.
-- Weights stay in kilograms in the database. The unit only changes how the app shows and accepts them.

create table if not exists public.user_settings (
  user_id uuid primary key default auth.uid() references auth.users (id) on delete cascade,
  -- ISO 3166-1 alpha-2, for example ID or US. Used later for local leaderboards.
  country text check (country is null or country ~ '^[A-Z]{2}$'),
  weight_unit text not null default 'kg' check (weight_unit in ('kg', 'lb')),
  currency text not null default 'IDR' check (currency in ('IDR', 'USD')),
  updated_at timestamptz not null default now()
);

alter table public.user_settings enable row level security;

drop policy if exists "user_settings owner" on public.user_settings;
create policy "user_settings owner" on public.user_settings
  for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- A price is in one currency and is never converted. Existing memberships keep their amount as IDR.
alter table public.memberships
  add column if not exists currency text not null default 'IDR';

alter table public.memberships drop constraint if exists memberships_currency_check;
alter table public.memberships
  add constraint memberships_currency_check check (currency in ('IDR', 'USD'));

-- ===== 20261028000100_set_timestamps.sql =====
-- When each set was completed, for the rest timer and the rest taken between sets.
-- Sets logged before this migration get their workout's start time, so they are never empty. Their rest
-- times are unknown, and the app hides any rest shown as zero.

alter table public.workout_sets add column if not exists completed_at timestamptz;

update public.workout_sets s
set completed_at = w.started_at
from public.workout_sessions w
where s.session_id = w.id and s.completed_at is null;

alter table public.workout_sets alter column completed_at set default now();
alter table public.workout_sets alter column completed_at set not null;

-- ===== 20261028000200_checkin_kind.sql =====
-- A check-in is now one of three kinds: gym, home (a workout at home) or rest.
-- Replaces the went_to_gym yes/no. Existing rows keep their meaning: yes becomes gym, no becomes rest.

alter table public.daily_checkins add column if not exists kind text;

-- Only runs while the old column still exists, so the migration can be repeated safely.
do $$
begin
  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'daily_checkins' and column_name = 'went_to_gym'
  ) then
    update public.daily_checkins
    set kind = case when went_to_gym then 'gym' else 'rest' end
    where kind is null;
  end if;
end $$;

update public.daily_checkins set kind = 'rest' where kind is null;

alter table public.daily_checkins alter column kind set default 'rest';
alter table public.daily_checkins alter column kind set not null;

alter table public.daily_checkins drop constraint if exists daily_checkins_kind_check;
alter table public.daily_checkins
  add constraint daily_checkins_kind_check check (kind in ('gym', 'home', 'rest'));

alter table public.daily_checkins drop column if exists went_to_gym;

-- ===== 20261028000300_xp_boosts.sql =====
-- Double XP Day boosters that have been used: one row per boosted day.
-- How many boosters a user has earned is worked out from their activity. Only the used ones are stored.
-- Rows can be read and added but not changed or removed, so a used booster stays used.

create table if not exists public.xp_boosts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  day date not null,
  created_at timestamptz not null default now(),
  unique (user_id, day)
);

alter table public.xp_boosts enable row level security;

drop policy if exists "xp_boosts read own" on public.xp_boosts;
create policy "xp_boosts read own" on public.xp_boosts
  for select to authenticated
  using (user_id = (select auth.uid()));

drop policy if exists "xp_boosts add own" on public.xp_boosts;
create policy "xp_boosts add own" on public.xp_boosts
  for insert to authenticated
  with check (user_id = (select auth.uid()));

-- ===== 20261028000400_leaderboard.sql =====
-- Leaderboard: one public row per user who chose to join.
-- Only the server writes here (with the service role key, which bypasses row level security).
-- Signed in users can read every row, so a board can be shown, and nobody can write directly,
-- so a score cannot be typed in from a browser. Leaving the board deletes the row.

create table if not exists public.leaderboard_entries (
  user_id uuid primary key references auth.users (id) on delete cascade,
  -- The nickname others see: 3 to 20 characters, no email or markup. Unique ignoring case.
  display_name text not null check (char_length(display_name) between 3 and 20),
  -- ISO 3166-1 alpha-2, copied from the user's settings when the score is synced.
  country text check (country is null or country ~ '^[A-Z]{2}$'),
  total_xp integer not null default 0 check (total_xp >= 0),
  week_xp integer not null default 0 check (week_xp >= 0),
  -- The Monday that week_xp belongs to. An older Monday means no XP yet this week.
  week_start date not null,
  level integer not null default 1 check (level >= 1),
  updated_at timestamptz not null default now()
);

create unique index if not exists leaderboard_entries_name_idx
  on public.leaderboard_entries (lower(display_name));
create index if not exists leaderboard_entries_total_idx
  on public.leaderboard_entries (total_xp desc, updated_at);
create index if not exists leaderboard_entries_country_idx
  on public.leaderboard_entries (country, total_xp desc, updated_at);
create index if not exists leaderboard_entries_week_idx
  on public.leaderboard_entries (week_start, week_xp desc, updated_at);

alter table public.leaderboard_entries enable row level security;

drop policy if exists "leaderboard read" on public.leaderboard_entries;
create policy "leaderboard read" on public.leaderboard_entries
  for select to authenticated
  using (true);

-- No insert, update or delete policy on purpose: without one, those are refused for everyone except
-- the service role.
